using UnityEngine;
using UnityEditor;
using System.Linq;
using FantasySurvival.WorldLighting;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            var g = UnityEngine.Object.FindFirstObjectByType<Gameplay397>();
            if (!g || !g.connected)
                throw new System.Exception("Runtime not connected");
            var h = g.player.host;
            var a = h.main.motion.animation.target;
            var s = UnityEngine.Object.FindFirstObjectByType<SkyLightingCycleController>();
            result.Log("502STATE play=" + EditorApplication.isPlaying + " paused=" + EditorApplication.isPaused + " newEnabled=" + HeadRegion502.Enabled + " oldEnabled=" + HairBoundary491.Enabled + " movement=" + g.player.player.GetComponent<PlayerMovement>().enabled + " animator=" + a.enabled + " locomotion=" + a.GetFloat("LocomotionSpeed") + " speed=" + a.speed + " capture=" + Time.captureDeltaTime + " automaticClock=" + s.IsAdvancingAutomatically + " hooks=" + string.Join(",", h.main.validateRender.GetInvocationList().Select(x => x.Target.GetType().Name)) + " clip=" + a.GetCurrentAnimatorClipInfo(0)[0].clip.name + " compiling=" + EditorApplication.isCompiling);
        }
    }
}
